-- 033: column definitions (docket B: every column has a definition; nullable columns say why).
-- Generated by scripts/lifecycle/build_definitions_migration.py from facts in the database plus hand-written text.
BEGIN;


-- analytics.dim_candidate
COMMENT ON COLUMN analytics.dim_candidate.candidate_key IS 'Surrogate key of this version of the candidate (Type 2): a candidate whose city or experience changes gets a new key.';
COMMENT ON COLUMN analytics.dim_candidate.candidate_profile_id IS 'Id of the candidate in profile.candidate_profile, shared by every version of the candidate.';
COMMENT ON COLUMN analytics.dim_candidate.current_city_name IS 'City of the candidate''s current location in this version. NULL when no current location is recorded.';
COMMENT ON COLUMN analytics.dim_candidate.total_experience_years IS 'Total years of work experience in this version of the candidate. NULL when the candidate recorded none.';
COMMENT ON COLUMN analytics.dim_candidate.profile_completeness_percentage IS 'Profile completeness, 0 to 100, in this version. NULL when it has not been computed.';
COMMENT ON COLUMN analytics.dim_candidate.primary_skill_name IS 'Name of the candidate''s primary skill in this version. NULL when the candidate has listed no skill.';
COMMENT ON COLUMN analytics.dim_candidate.valid_from IS 'Start of the period in which this version was current.';
COMMENT ON COLUMN analytics.dim_candidate.valid_to IS 'End of the period in which this version was current. NULL for the current version.';
COMMENT ON COLUMN analytics.dim_candidate.is_current IS 'True when current. Default true.';

-- analytics.dim_date
COMMENT ON COLUMN analytics.dim_date.date_key IS 'Calendar day as the integer YYYYMMDD (for example 20261028); the key facts join to.';
COMMENT ON COLUMN analytics.dim_date.calendar_date IS 'Calendar date of calendar.';
COMMENT ON COLUMN analytics.dim_date.day_of_month IS 'Day of the month, 1 to 31.';
COMMENT ON COLUMN analytics.dim_date.day_name IS 'English name of the weekday, padded by the database to nine characters.';
COMMENT ON COLUMN analytics.dim_date.day_of_week IS 'ISO weekday, 1 (Monday) to 7 (Sunday).';
COMMENT ON COLUMN analytics.dim_date.month_number IS 'Month of the year, 1 to 12.';
COMMENT ON COLUMN analytics.dim_date.month_name IS 'English name of the month, padded by the database.';
COMMENT ON COLUMN analytics.dim_date.quarter_number IS 'Calendar quarter, 1 to 4.';
COMMENT ON COLUMN analytics.dim_date.year_number IS 'Calendar year.';
COMMENT ON COLUMN analytics.dim_date.is_weekend IS 'True when weekend. Default None.';

-- analytics.dim_job_posting
COMMENT ON COLUMN analytics.dim_job_posting.job_posting_key IS 'Surrogate key of the job in the star schema.';
COMMENT ON COLUMN analytics.dim_job_posting.job_posting_id IS 'Id of the job in recruitment.job_posting.';
COMMENT ON COLUMN analytics.dim_job_posting.organization_key IS 'Reference to analytics.dim_organization (organization key). Required.';
COMMENT ON COLUMN analytics.dim_job_posting.job_title IS 'Title of the job as last loaded (Type 1: the latest value wins).';
COMMENT ON COLUMN analytics.dim_job_posting.job_role_name IS 'Name of the job''s role. NULL when the job has no role.';
COMMENT ON COLUMN analytics.dim_job_posting.industry_name IS 'Name of the job''s industry. NULL when the job has none.';
COMMENT ON COLUMN analytics.dim_job_posting.employment_type_code IS 'Employment type code (for example full_time). NULL when the job has none.';
COMMENT ON COLUMN analytics.dim_job_posting.work_type_code IS 'Work arrangement code (on_site, remote, hybrid). NULL when the job has none.';
COMMENT ON COLUMN analytics.dim_job_posting.currency_code IS 'ISO 4217 currency of salary_min and salary_max. NULL when the job discloses no salary.';
COMMENT ON COLUMN analytics.dim_job_posting.salary_min IS 'Lowest salary offered, in currency_code. NULL when the job discloses no salary.';
COMMENT ON COLUMN analytics.dim_job_posting.salary_max IS 'Highest salary offered, in currency_code. NULL when the job discloses no salary.';
COMMENT ON COLUMN analytics.dim_job_posting.published_date_key IS 'Reference to analytics.dim_date (published date key). NULL when there is none.';

-- analytics.dim_organization
COMMENT ON COLUMN analytics.dim_organization.organization_key IS 'Surrogate key of this version of the organisation (Type 2).';
COMMENT ON COLUMN analytics.dim_organization.organization_id IS 'Id of the organisation in recruitment.organization, shared by every version.';
COMMENT ON COLUMN analytics.dim_organization.organization_name IS 'Name in this version.';
COMMENT ON COLUMN analytics.dim_organization.organization_type IS 'Type in this version (for example employer, agency).';
COMMENT ON COLUMN analytics.dim_organization.country_code IS 'ISO 3166 alpha-3 code of the organisation''s country. NULL when no country is recorded.';
COMMENT ON COLUMN analytics.dim_organization.industry_name IS 'The industry in which the organisation posts most jobs. NULL when it has posted none with an industry.';
COMMENT ON COLUMN analytics.dim_organization.valid_from IS 'Start of the period in which this version was current.';
COMMENT ON COLUMN analytics.dim_organization.valid_to IS 'End of the period in which this version was current. NULL for the current version.';
COMMENT ON COLUMN analytics.dim_organization.is_current IS 'True when current. Default true.';

-- analytics.fact_application_event
COMMENT ON COLUMN analytics.fact_application_event.id IS 'Surrogate primary key (64-bit identity). Never reused, never shown to users.';
COMMENT ON COLUMN analytics.fact_application_event.candidate_application_id IS 'Application the event belongs to (recruitment.candidate_application).';
COMMENT ON COLUMN analytics.fact_application_event.date_key IS 'Reference to analytics.dim_date (date key). Required.';
