COMMENT ON COLUMN analytics.fact_application_event.previous_status IS 'Status the application left. NULL for the first event, when it was created.';
COMMENT ON COLUMN analytics.fact_application_event.new_status IS 'Status the application entered.';
COMMENT ON COLUMN analytics.fact_application_event.status_cycle_time_hours IS 'Hours the application spent in previous_status. NULL for the first event, which has no previous status.';
COMMENT ON COLUMN analytics.fact_application_event.is_terminal_state IS 'True when terminal state. Default false.';
COMMENT ON COLUMN analytics.fact_application_event.event_timestamp IS 'When the status change happened (UTC).';

-- analytics.fact_gig_performance
COMMENT ON COLUMN analytics.fact_gig_performance.id IS 'Surrogate primary key (64-bit identity). Never reused, never shown to users.';
COMMENT ON COLUMN analytics.fact_gig_performance.gig_assignment_id IS 'Finished assignment this row summarises (gig.gig_assignment).';
COMMENT ON COLUMN analytics.fact_gig_performance.organization_key IS 'Reference to analytics.dim_organization (organization key). Required.';
COMMENT ON COLUMN analytics.fact_gig_performance.completion_date_key IS 'Reference to analytics.dim_date (completion date key). NULL when there is none.';
COMMENT ON COLUMN analytics.fact_gig_performance.agreed_amount IS 'Price agreed for the assignment, in currency_code.';
COMMENT ON COLUMN analytics.fact_gig_performance.actual_reconciled_earnings IS 'Earnings the fulfilment system reported, in currency_code. 0 when none have been reconciled.';
COMMENT ON COLUMN analytics.fact_gig_performance.currency_code IS 'ISO 4217 currency of the amount(s) in this row, three capital letters.';
COMMENT ON COLUMN analytics.fact_gig_performance.duration_days IS 'Number of days.';
COMMENT ON COLUMN analytics.fact_gig_performance.client_rating IS 'Requester''s overall rating, 1 to 5. NULL when the assignment was not rated.';
COMMENT ON COLUMN analytics.fact_gig_performance.assignment_status IS 'Final status of the assignment: completed or terminated.';

-- analytics.fact_wallet_transaction
COMMENT ON COLUMN analytics.fact_wallet_transaction.id IS 'Surrogate primary key (64-bit identity). Never reused, never shown to users.';
COMMENT ON COLUMN analytics.fact_wallet_transaction.wallet_id IS 'Wallet the entry belongs to (commercial.wallet).';
COMMENT ON COLUMN analytics.fact_wallet_transaction.organization_key IS 'Reference to analytics.dim_organization (organization key). Required.';
