COMMENT ON COLUMN audit.action_catalogue.created_by_user_account_id IS 'Account that created the row, taken from the session. NULL when the system created it (seed, migration, scheduled job).';
COMMENT ON COLUMN audit.action_catalogue.updated_by_user_account_id IS 'Account that last changed the row, taken from the session. NULL when the system changed it.';

-- audit.audit_event
COMMENT ON COLUMN audit.audit_event.id IS 'Surrogate primary key (64-bit identity). Never reused, never shown to users.';
COMMENT ON COLUMN audit.audit_event.actor_user_account_id IS 'Reference to core.user_account (actor user account). NULL when there is none.';
COMMENT ON COLUMN audit.audit_event.impersonator_user_account_id IS 'Reference to core.user_account (impersonator user account). NULL when there is none.';
COMMENT ON COLUMN audit.audit_event.action IS 'Reference to audit.action_catalogue (action). Required.';
COMMENT ON COLUMN audit.audit_event.entity_schema IS 'Schema of the table the action concerned.';
