COMMENT ON COLUMN audit.audit_event.new_values_json IS 'Row as it is after the change, secrets removed. NULL for events that delete or only observe.';
COMMENT ON COLUMN audit.audit_event.client_ip IS 'Address the request came from. NULL for actions not made through a request. Personal data.';
COMMENT ON COLUMN audit.audit_event.user_agent IS 'Client software string. NULL when not available. Personal data.';
COMMENT ON COLUMN audit.audit_event.recorded_at IS 'Instant (UTC) at which this row''s recorded happened.';

